-- Dumping structure for table sanchaya.inbound_items
CREATE TABLE IF NOT EXISTS `inbound_items` (
  `id` int NOT NULL AUTO_INCREMENT,
  `inbound_order_id` int NOT NULL,
  `od_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'OD Number per item (from planning)',
  `so_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SO Number per item (from planning)',
  `product_id` int NOT NULL,
  `batch_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `location` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `quantity` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'Order quantity',
  `uom` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'Drum' COMMENT 'Unit of Measure',
  `actual_qty` decimal(10,2) DEFAULT '0.00' COMMENT 'Actual received quantity',
  `pallet` decimal(10,2) DEFAULT '0.00' COMMENT 'Pallet quantity',
  `pallet_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nomor label palet fisik, e.g. PLT-001',
  `manufacture_date` date DEFAULT NULL COMMENT 'Manufacture/Production date',
  `exp_date` date DEFAULT NULL COMMENT 'Expiry date',
  `stock_status` enum('Accepted','Rejected','Pending') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Pending' COMMENT 'Stock acceptance status - auto-set from in_process_status',
  `in_process_status` enum('Dues In','Goods Received','ATP','Unserviceable','Picked') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Dues In',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `batch_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_inbound_order` (`inbound_order_id`),
  KEY `idx_product` (`product_id`),
  KEY `idx_batch` (`batch_no`),
  KEY `idx_location` (`location`),
  KEY `idx_exp_date` (`exp_date`),
  KEY `idx_od_number` (`od_number`),
  KEY `idx_so_number_item` (`so_number`),
  KEY `idx_batch_number` (`batch_number`),
  CONSTRAINT `fk_inbound_item_order` FOREIGN KEY (`inbound_order_id`) REFERENCES `inbound_orders` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_inbound_item_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Dumping data for table sanchaya.inbound_items: ~0 rows (approximately)

-- Dumping structure for table sanchaya.inbound_orders
CREATE TABLE IF NOT EXISTS `inbound_orders` (
  `id` int NOT NULL AUTO_INCREMENT,
  `order_number` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `order_date` date NOT NULL,
  `carrier_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Carrier / Transporter name (free text)',
  `container_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Container number',
  `po_number` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shipment_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Shipment Number',
  `do_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Delivery Order Number',
  `armada_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Vehicle/Armada number',
  `production_date` date DEFAULT NULL COMMENT 'Production date for auto expiry calculation',
  `expected_date` date DEFAULT NULL,
  `status` enum('Draft','Dues In','Receiving','Good Received','Goods Received','Unserviceable','Picked','ATP','Completed','Cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Draft',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `remarks` text COLLATE utf8mb4_unicode_ci,
  `received_by` int DEFAULT NULL COMMENT 'User who received',
  `received_by_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Name of receiver',
  `received_date` date DEFAULT NULL COMMENT 'Actual receive date',
  `created_by` int NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_number` (`order_number`),
  UNIQUE KEY `uk_order_number` (`order_number`),
  KEY `idx_order_date` (`order_date`),
  KEY `idx_status` (`status`),
  KEY `idx_container_no` (`container_no`),
  KEY `idx_armada_no` (`armada_no`),
  KEY `idx_received_by` (`received_by`),
  KEY `fk_inbound_created_by` (`created_by`),
  KEY `idx_shipment_no` (`shipment_no`),
  CONSTRAINT `fk_inbound_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_inbound_received_by` FOREIGN KEY (`received_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

