-- Dumping structure for table sanchaya.location_allocations
CREATE TABLE IF NOT EXISTS `location_allocations` (
  `id` int NOT NULL AUTO_INCREMENT,
  `reference_type` enum('Inbound','Outbound','Stock') COLLATE utf8mb4_unicode_ci NOT NULL,
  `reference_id` int NOT NULL,
  `item_id` int NOT NULL COMMENT 'Item ID from inbound_items/outbound_items',
  `pallet_number` int NOT NULL COMMENT 'Sequential pallet number',
  `location` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `quantity` decimal(10,2) NOT NULL,
  `uom` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'Drum',
  `is_full` tinyint(1) DEFAULT '1' COMMENT '1 = full pallet, 0 = partial',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_reference` (`reference_type`,`reference_id`),
  KEY `idx_item` (`item_id`),
  KEY `idx_location` (`location`),
  KEY `idx_pallet_number` (`pallet_number`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Dumping data for table sanchaya.location_allocations: ~0 rows (approximately)

-- Dumping structure for table sanchaya.location_master
CREATE TABLE IF NOT EXISTS `location_master` (
  `id` int NOT NULL AUTO_INCREMENT,
  `location_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'e.g. CA01A01',
  `aisle` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rack` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `row_name` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `position` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `zone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Bulk / Carton / Pail / Special',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `location_code` (`location_code`),
  KEY `idx_aisle` (`aisle`),
  KEY `idx_zone` (`zone`)
) ENGINE=InnoDB AUTO_INCREMENT=5184 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Master data semua lokasi gudang';

