-- Dumping structure for table sanchaya.stock
CREATE TABLE IF NOT EXISTS `stock` (
  `id` int NOT NULL AUTO_INCREMENT,
  `product_id` int NOT NULL,
  `batch_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `location` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `quantity` decimal(10,2) NOT NULL DEFAULT '0.00',
  `uom` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'Drum' COMMENT 'Unit of Measure',
  `uom_type` enum('Drum','Carton','Pail') COLLATE utf8mb4_unicode_ci DEFAULT 'Drum',
  `uom_per_pallet` int DEFAULT '4',
  `pallet` decimal(10,2) DEFAULT '0.00' COMMENT 'Pallet quantity',
  `manufacture_date` date DEFAULT NULL,
  `production_date` date DEFAULT NULL,
  `expiry_date` date DEFAULT NULL,
  `stock_status` enum('Available','Reserved','Expired','Dues In','Rejected') COLLATE utf8mb4_unicode_ci DEFAULT 'Available',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_product` (`product_id`),
  KEY `idx_batch` (`batch_number`),
  KEY `idx_location` (`location`),
  KEY `idx_expiry` (`expiry_date`),
  KEY `idx_stock_status` (`stock_status`),
  KEY `idx_manufacture_date` (`production_date`),
  CONSTRAINT `fk_stock_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=138 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

