-- Dumping structure for table sanchaya.stock_locations
CREATE TABLE IF NOT EXISTS `stock_locations` (
  `id` int NOT NULL AUTO_INCREMENT,
  `stock_id` int DEFAULT NULL COMMENT 'FK → stock.id, diisi saat inbound complete (NULL saat inbound masih Draft/Open)',
  `location_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'FK → location_master.location_code',
  `pallet_seq` smallint NOT NULL DEFAULT '1' COMMENT 'Pallet sequence within this inbound item',
  `quantity` decimal(10,2) NOT NULL DEFAULT '0.00',
  `original_quantity` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'Qty saat inbound — tidak berubah walaupun sudah dipick',
  `uom` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'EA',
  `is_full_pallet` tinyint(1) DEFAULT '1',
  `batch_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `inbound_item_id` int DEFAULT NULL,
  `status` enum('Available','Reserved','Picked','Empty') COLLATE utf8mb4_unicode_ci DEFAULT 'Available',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_stock` (`stock_id`),
  KEY `idx_location` (`location_code`),
  KEY `idx_status` (`status`),
  KEY `idx_batch` (`batch_number`),
  KEY `idx_inbound_item_id` (`inbound_item_id`)
) ENGINE=InnoDB AUTO_INCREMENT=66 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Stok per pallet per lokasi';

